/** How many street tile variants a theme may have (theme package: street.tile.<mode>, up to 4). */
export const STREET_VARIANTS = 4;

/** The <html> attribute that names this load's street tile variant ("1".."4"; fanous-street.css shows it). */
export const STREET_VARIANT_ATTR = 'data-fanous-street-variant';

/** Cookie that pins the street variant for visual tests (1-4); without a valid one each response picks at random. */
export const STREET_VARIANT_COOKIE = 'aun_street_variant';

/**
 * The street tile variant for one HTML response, picked on the server so the page arrives with
 * <html data-fanous-street-variant="N"> already set (no inline script, nothing swaps after paint).
 * Call it per response, never per cached copy: an edge-cached page sets the attribute after the
 * cache read (HTMLRewriter), so each visit still gets its own variant. `cookieHeader` is the
 * request's Cookie header; a valid aun_street_variant cookie wins (visual tests pin with it).
 * It runs for every theme; it only matters where the theme has a street.
 */
export function pickStreetVariant(cookieHeader, random = Math.random) {
  const pinned = /(?:^|;)\s*aun_street_variant=([1-9])\s*(?:;|$)/.exec(cookieHeader || '');
  if (pinned && Number(pinned[1]) <= STREET_VARIANTS) return Number(pinned[1]);
  return 1 + Math.min(STREET_VARIANTS - 1, Math.floor(random() * STREET_VARIANTS));
}

// Fanous lantern street: the shared module every Al Ummah Now app includes (videos, admin, www,
// CMS, sign-in, profile, accounts admin). Plain JavaScript, no dependencies, so other repos can
// vendor this file as is (with fanous-street.css).
//
// The street is pre-made art, not drawn by script: the theme's tokens give one wide image tile of
// strings and lit lanterns (--fanous-street-tile, repeated behind the whole page with no seam) and
// the soft distant lights (--fanous-street-lights). fanous-street.css paints them behind every
// element when <html> has the class fanous-street. This module only sets that class when the
// active theme switches the street on (--fanous-street-on: 1) and keeps
// it in step with theme and mode changes. Nothing runs on scroll or resize, there is no drawing,
// no measuring and no animation, so the street costs nothing after the first paint.
// <html data-fanous-street="off"> switches it off for a page.

/** Whether the active theme and mode switch the street on (and the page allows it). */
export function streetEnabled(doc = globalThis.document) {
  if (doc.documentElement.dataset.fanousStreet === 'off') return false;
  return doc.defaultView.getComputedStyle(doc.documentElement).getPropertyValue('--fanous-street-on').trim() === '1';
}

/** Applies the street for the current theme and mode. Returns whether it is on. */
export function renderStreet(doc = globalThis.document) {
  const on = streetEnabled(doc);
  doc.documentElement.classList.toggle('fanous-street', on);
  return { on };
}

/**
 * Starts the street on this page and keeps it in step with the theme and mode.
 * Safe to call more than once; returns a function that stops it and removes the class.
 */
export function startStreet(doc = globalThis.document) {
  const win = doc.defaultView;
  const html = doc.documentElement;
  const sync = () => renderStreet(doc);
  // A theme or mode change (class .dark, data-theme, data-mode) takes effect at once. Setting the
  // class to the state it already has changes nothing, so the module's own toggle cannot loop.
  const obs = new win.MutationObserver(sync);
  obs.observe(html, { attributes: true, attributeFilter: ['class', 'data-theme', 'data-mode', 'data-fanous-street'] });
  const dark = win.matchMedia('(prefers-color-scheme: dark)');
  dark.addEventListener?.('change', sync);
  sync();
  return () => {
    obs.disconnect();
    dark.removeEventListener?.('change', sync);
    html.classList.remove('fanous-street');
  };
}
